WITH exploded AS (SELECT id, effective_from, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) x AS tier_value) SELECT id, tier_value, AVG(tier_value) OVER (PARTITION BY YEAR(effective_from)) AS effective_from_year_avg_tier_value, RANK() OVER (ORDER BY tier_value DESC NULLS LAST) AS tier_value_rank, PERCENT_RANK() OVER (ORDER BY tier_value NULLS FIRST) AS tier_value_percent_rank, DENSE_RANK() OVER (ORDER BY tier_value NULLS FIRST) AS tier_value_dense_rank FROM exploded WHERE tier_value <> 66
